-- 0049: basal ganglia, indirect pathway, both sides (the product owner's spreadsheet brain_region_new_platform_4.xlsx).
--
-- The straight up/down line (TTB on the right, BTT on the left) may be continuous as well as in intervals ("0, 1").
-- The sideways and diagonal line stays intervals only. With this the table equals the spreadsheet cell for cell.
--
-- Data only. Generated by settingRevisionSql(); a test checks this file against it.

UPDATE app.region_setting s SET bg_temperature = 'cold', bg_types = ARRAY['textured', 'solid']::text[], motion = '[{"movement_types":[1],"directions":["rtl","brdtl"]},{"movement_types":[0,1],"directions":["ttb"]}]'::jsonb, target_locations = ARRAY['W', 'SW', 'NW', 'N', 'S']::text[], rotation = 'cw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'right.subcortical.basal_ganglia_indirect';
UPDATE app.region_setting s SET bg_temperature = 'warm', bg_types = ARRAY['textured', 'solid']::text[], motion = '[{"movement_types":[1],"directions":["ltr","bldtr"]},{"movement_types":[0,1],"directions":["btt"]}]'::jsonb, target_locations = ARRAY['E', 'SE', 'NE', 'N', 'S']::text[], rotation = 'ccw', clinical_status = 'draft', revision = s.revision + 1, updated_at = now() FROM app.brain_region b WHERE b.id = s.sublobe_id AND b.path = 'left.subcortical.basal_ganglia_indirect';
